CREATE TABLE IF NOT EXISTS richo_trace_spans_l2(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trace_id text NOT NULL,span_id text NOT NULL,parent_span_id text,service text NOT NULL,operation text NOT NULL,duration_ms numeric(18,4),status text NOT NULL,attributes jsonb NOT NULL DEFAULT '{}'::jsonb,correlation_id text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(trace_id,span_id));
CREATE TABLE IF NOT EXISTS richo_slo_definitions_l2(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),service text NOT NULL,name text NOT NULL,target numeric(10,8) NOT NULL,window_minutes integer NOT NULL,error_budget_policy jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_synthetic_probe_results_l2(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),probe_name text NOT NULL,passed boolean NOT NULL,status_code integer,latency_ms numeric(18,4),reason text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_incident_timeline_l2(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id text NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb,occurred_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_capacity_forecasts_l2(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),resource text NOT NULL,current_utilization numeric(10,6),projected_utilization numeric(10,6),days_to_limit numeric(18,4),risk text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS richo_trace_lookup_l2 ON richo_trace_spans_l2(trace_id,created_at);
